import { beforeEach, afterEach, describe, expect, it, vi } from 'vitest'
import { renderToStaticMarkup } from 'react-dom/server'

const hooks = vi.hoisted(() => ({ state: undefined as any, effect: undefined as any }))
vi.mock('react', async (importOriginal) => {
  const react = await importOriginal<typeof import('react')>()
  return {
    ...react,
    useState: (initial: unknown) => {
      if (hooks.state === undefined) hooks.state = initial
      return [hooks.state, (state: unknown) => { hooks.state = state }]
    },
    useEffect: (effect: unknown) => { hooks.effect = effect },
  }
})

import Dashboard from './app/Dashboard'

describe('dashboard data loading', () => {
  beforeEach(() => { hooks.state = undefined; hooks.effect = undefined })
  afterEach(() => { vi.unstubAllGlobals() })

  it('starts all requests before any resolve and displays each response', async () => {
    const resolve: Array<(value: unknown) => void> = []
    const fetchMock = vi.fn(() => new Promise((r) => resolve.push(r)))
    vi.stubGlobal('fetch', fetchMock)
    expect(renderToStaticMarkup(Dashboard())).toContain('Loading dashboard data')
    const cleanup = hooks.effect()
    expect(fetchMock.mock.calls.map((call) => call[0])).toEqual([
      '/api/analytics', '/api/notifications', '/api/settings',
    ])
    for (const [index, value] of ['traffic', 'message', 'theme'].entries()) {
      resolve[index]({ ok: true, json: async () => ({ value }) })
    }
    await vi.waitFor(() => expect(hooks.state.status).toBe('success'))
    const html = renderToStaticMarkup(Dashboard())
    for (const value of ['Analytics', 'Notifications', 'Settings', 'traffic', 'message', 'theme']) {
      expect(html).toContain(value)
    }
    cleanup()
  })

  it('reports failed responses and aborts outstanding requests', async () => {
    const fetchMock = vi.fn()
      .mockResolvedValueOnce({ ok: false, status: 500 })
      .mockImplementation(() => new Promise(() => {}))
    vi.stubGlobal('fetch', fetchMock)
    Dashboard()
    const cleanup = hooks.effect()
    await vi.waitFor(() => expect(hooks.state.status).toBe('error'))
    expect(renderToStaticMarkup(Dashboard())).toContain('Unable to load dashboard data')
    expect(fetchMock.mock.calls[1][1].signal.aborted).toBe(true)
    cleanup()
  })

  it('aborts requests and ignores results after unmount', async () => {
    const resolve: Array<(value: unknown) => void> = []
    const fetchMock = vi.fn(() => new Promise((r) => resolve.push(r)))
    vi.stubGlobal('fetch', fetchMock)
    Dashboard()
    const cleanup = hooks.effect()
    cleanup()
    expect(fetchMock.mock.calls[0][1].signal.aborted).toBe(true)
    for (const r of resolve) r({ ok: true, json: async () => ({ value: 1 }) })
    await new Promise((r) => setTimeout(r, 0))
    expect(hooks.state.status).toBe('loading')
  })
})
EOF
